def _esc(s):
    """str → 引号内文本：转义反斜杠/双引号/换行/回车/制表；其余 C0（0x00-0x1F）
    与 U+2028/U+2029 拒收（ValueError 含码位）——保住 canonical 文本行不被撕裂。
    """
    out = []
    for c in s:
        if c == "\\":
            out.append("\\\\")
        elif c == '"':
            out.append('\\"')
        elif c == "\n":
            out.append("\\n")
        elif c == "\r":
            out.append("\\r")
        elif c == "\t":
            out.append("\\t")
        else:
            cp = ord(c)
            if cp < 0x20 or cp in (0x2028, 0x2029):
                raise ValueError("字符码位 U+%04X 拒收：canonical 文本不容纳未转义控制字符" % cp)
            out.append(c)
    return "".join(out)


def _unescape(s):
    """引号内文本 → str（_esc 的逆；未知转义序列拒绝）。"""
    out = []
    i = 0
    while i < len(s):
        c = s[i]
        if c != "\\":
            out.append(c)
            i += 1
            continue
        if i + 1 >= len(s):
            raise ValueError("字符串以孤立反斜杠结尾")
        nxt = s[i + 1]
        if nxt == "\\":
            out.append("\\")
        elif nxt == '"':
            out.append('"')
        elif nxt == "n":
            out.append("\n")
        elif nxt == "r":
            out.append("\r")
        elif nxt == "t":
            out.append("\t")
        else:
            raise ValueError("未知转义序列: \\%s" % nxt)
        i += 2
    return "".join(out)


def _render_variant(v):
    """variant → token 对：num <%.6f> / str "<引号串>" / bool 0|1。"""
    tag, payload = _variant_tag_value(v)
    if tag == VARIANT_TAG_NUM:
        return ["num", "%.6f" % qf(payload)]
    if tag == VARIANT_TAG_STR:
        return ["str", '"' + _esc(payload) + '"']
    return ["bool", "1" if payload else "0"]


def _render_tok(typ, v):
    """单字段 → token 列表（f32/f64 一律 %.6f；rgba8 四个十进制；f32[] 点数+坐标）。"""
    if typ in ("u8", "u32"):
        return [str(int(v))]
    if typ in ("f32", "f64"):
        return ["%.6f" % qf(v)]
    if typ == "rgba8":
        return [str(int(c)) for c in v]
    if typ == "str":
        return ['"' + _esc(v) + '"']
    if typ == "f32[]":
        toks = [str(len(v))]
        for x, y in v:
            toks.append("%.6f" % qf(x))
            toks.append("%.6f" % qf(y))
        return toks
    if typ == "variant":
        return _render_variant(v)
    raise ValueError("未知类型: %r" % typ)


def _asset_hex(tok):
    """hex 载荷 token → bytes（"-" 记空载荷；非法 hex → ValueError 含肇事 token）。"""
    if tok == "-":
        return b""
    try:
        return bytes.fromhex(tok)
    except ValueError:
        raise ValueError("asset hex 载荷非法: %r" % tok) from None


def _render_asset(fields):
    """asset fields dict → canonical token 列表（kind 用名字；hex 载荷，空载荷记 "-"）。

    形态（spec §6.3）：asset image <id> <w> <h> <hex> / asset canvas <id> <w> <h> /
    asset quad <id> <x> <y> <w> <h> <sw> <sh> / asset font <id> <size> <hex>。
    浮点先 qf 入量化域再 %.6f，与二进制形态量化后一致。
    """
    kind = fields["kind"]
    name = _ASSET_KIND_NAMES.get(kind)
    if name is None:
        raise ValueError("asset kind 非法: %r" % (kind,))
    toks = ["asset", name, str(int(fields["id"]))]
    if kind == ASSET_KIND_CANVAS:
        toks.extend((str(int(fields["w"])), str(int(fields["h"]))))
    elif kind == ASSET_KIND_QUAD:
        toks.extend("%.6f" % qf(fields[k]) for k in ("x", "y", "w", "h", "sw", "sh"))
    else:  # image / font：尺寸或字号后接 hex 载荷
        if kind == ASSET_KIND_IMAGE:
            toks.extend((str(int(fields["w"])), str(int(fields["h"]))))
        else:
            toks.append("%.6f" % qf(fields["size"]))
        if fields.get("font_src", 0):  # 字节引用形态（v1.2.7）：=srcid
            toks.append("=%d" % int(fields["font_src"]))
            return toks
        hexed = fields["data"].hex()
        toks.append(hexed if hexed else "-")
    return toks


def render_line(op, fields):
    """行 → canonical 文本（空格分隔 token）；asset 走 _render_asset（kind 用名字）。"""
    try:
        spec = _BY_OP[op]
    except KeyError:
        raise ValueError("未知 op: %r" % op) from None
    if op == "asset" or spec["variadic"] == "payload...":
        return " ".join(_render_asset(fields))
    toks = [op]
    for name, typ in spec["fields"]:
        toks.extend(_render_tok(typ, fields[name]))
    if spec["variadic"] == "args...":
        args = fields["args"]
        toks.append(str(len(args)))
        for v in args:
            toks.extend(_render_variant(v))
    return " ".join(toks)


def _tokenize(line):
    """文本行 → token 列表；带引号字符串为单 token（含两侧引号，转义不拆分）。"""
    toks = []
    i, n = 0, len(line)
    while i < n:
        c = line[i]
        if c in " \t\r":
            i += 1
            continue
        if c == '"':
            j = i + 1
            while j < n:
                if line[j] == "\\":
                    j += 2
                    continue
                if line[j] == '"':
                    break
                j += 1
            if j >= n:
                raise ValueError("字符串 token 未闭合")
            toks.append(line[i:j + 1])
            i = j + 1
        else:
            j = i
            while j < n and line[j] not in " \t\r":
                j += 1
            toks.append(line[i:j])
            i = j
    return toks


def _parse_asset(toks, pos):
    """token 列表 → (asset fields dict, 新位置)；_render_asset 的逆。

    kind 用名字，未知名 → ValueError 含 op 与肇事 token；hex 载荷 "-" 记空；
    浮点 qf 入域，与二进制解码一致。
    """
    op = toks[0]

    def take():
        nonlocal pos
        if pos >= len(toks):
            raise ValueError("asset 行 token 不足")
        tok = toks[pos]
        pos += 1
        return tok

    name = take()
    if name not in _ASSET_KIND_BY_NAME:
        raise ValueError("asset kind 名非法: %r" % name)
    kind = _ASSET_KIND_BY_NAME[name]
    fields = {"kind": kind, "id": int(take())}
    if kind == ASSET_KIND_IMAGE:
        fields["w"] = int(take())
        fields["h"] = int(take())
        fields["data"] = _asset_hex(take())
    elif kind == ASSET_KIND_CANVAS:
        fields["w"] = int(take())
        fields["h"] = int(take())
    elif kind == ASSET_KIND_QUAD:
        for key in ("x", "y", "w", "h", "sw", "sh"):
            fields[key] = qf(float(take()))
    else:  # font
        fields["size"] = qf(float(take()))
        tok = take()
        if tok.startswith("="):  # 字节引用形态（v1.2.7）：=srcid
            fields["font_src"] = int(tok[1:])
            fields["data"] = b""
        else:
            fields["data"] = _asset_hex(tok)
    return fields, pos


def parse_line(line):
    """canonical 文本 → (op, fields dict)（render_line 的逆）；asset 走 _parse_asset。"""
    toks = _tokenize(line)
    if not toks:
        raise ValueError("空行")
    op = toks[0]
    try:
        spec = _BY_OP[op]
    except KeyError:
        raise ValueError("未知 op: %r" % op) from None
    pos = 1

    def take():
        nonlocal pos
        if pos >= len(toks):
            raise ValueError("%s 行 token 不足" % op)
        tok = toks[pos]
        pos += 1
        return tok

    def parse_variant():
        tag = take()
        if tag == "num":
            return qf(float(take()))
        if tag == "str":
            tok = take()
            if len(tok) < 2 or tok[0] != '"' or tok[-1] != '"':
                raise ValueError("variant str token 缺引号: %r" % tok)
            return (_unescape(tok[1:-1]),)
        if tag == "bool":
            return (take() == "1",)
        raise ValueError("variant tag 非法: %r" % tag)

    def parse_one(typ):
        if typ in ("u8", "u32"):
            return int(take())
        if typ in ("f32", "f64"):
            return qf(float(take()))
        if typ == "rgba8":
            return (int(take()), int(take()), int(take()), int(take()))
        if typ == "str":
            tok = take()
            if len(tok) < 2 or tok[0] != '"' or tok[-1] != '"':
                raise ValueError("str token 缺引号: %r" % tok)
            return _unescape(tok[1:-1])
        if typ == "f32[]":
            count = int(take())
            pts = []
            for _ in range(count):
                x = qf(float(take()))
                y = qf(float(take()))
                pts.append((x, y))
            return pts
        if typ == "variant":
            return parse_variant()
        raise ValueError("未知类型: %r" % typ)

    fields = {}
    if op == "asset" or spec["variadic"] == "payload...":
        fields, pos = _parse_asset(toks, pos)
    else:
        for name, typ in spec["fields"]:
            fields[name] = parse_one(typ)
        if spec["variadic"] == "args...":
            argc = int(take())
            fields["args"] = [parse_variant() for _ in range(argc)]
    if pos != len(toks):
        raise ValueError("%s 行多余 token: %r" % (op, toks[pos:]))
    return op, fields


def self_test_samples():
    """每 op 至少一条自检样本（encode→decode round-trip 基准；asset 按 kind 各一）。

    variant 规范形（解码不动点）：num=裸数（call 的 args）、str/bool=单元素 tuple
    （ev 的 args）；st 的 val 字段按裸数直接给。样本数据单一来源在
    tools/fr_gen/samples.py（与 C 自检生成共用），此处转调保持公共 API 不变。
    """
    from tools.fr_gen.samples import samples

    return samples()
